#include <iostream>
#include <string>
using namespace std;

int main() {
    string s;
    getline(cin, s);
    int upper=0, lower=0, digit=0, space=0, other=0;
    for (int i = 0; i < s.length(); i++) {
        if (s[i] >= 'A' && s[i] <= 'Z') upper++;
        else if (s[i] >= 'a' && s[i] <= 'z') lower++;
        else if (s[i] >= '0' && s[i] <= '9') digit++;
        else if (s[i] == ' ') space++;
        else other++;
    }
    cout << upper << endl << lower << endl << digit << endl << space << endl << other << endl;
    return 0;
}

#include <iostream>
#include <vector>
using namespace std;

int main() {
    int n, m;
    cin >> n >> m;
    vector<int> people;
    for (int i = 1; i <= n; i++) people.push_back(i);
    int idx = 0;
    for (int i = 0; i < n; i++) {
        idx = (idx + m - 1) % people.size();
        if (i > 0) cout << " ";
        cout << people[idx];
        people.erase(people.begin() + idx);
        if (idx >= (int)people.size()) idx = 0;
    }
    cout << endl;
    return 0;
}
